fn exact_without_checksum(version: &str) -> ProviderObservationV1 {
    ProviderObservationV1::Exact {
        evidence: ProviderEvidenceV1::RegistryVersion {
            version: Version::parse(version, VersionGrammar::SemVer).unwrap(),
            checksum: None,
            yanked: None,
        },
    }
}

