fn a_crate_the_registry_has_never_heard_of_is_absent() {
    let (observation, _) = observe_cargo(&operation("testreg", "core-crate-no-such-crate-zz", "1.0.0"));
    assert_eq!(observation, ProviderObservationV1::Absent);
}

