/// `python -m build --sdist --wheel --outdir <outdir>` in the package directory, with the first interpreter on PATH
/// and `SOURCE_DATE_EPOCH` set so backends that honor it stamp the same time into every rebuild.
pub fn pypi_build_argv(
    workspace_root: &Path,
    package_dir: &Path,
    outdir: &Path,
    source_date_epoch: u64,
) -> Result<Argv, GraphError> {
    let interpreter = resolve_python_interpreter(std::env::var_os("PATH").as_deref())?;
    Ok(Argv {
        program: "env".to_string(),
        args: vec![
            format!("SOURCE_DATE_EPOCH={source_date_epoch}"),
            interpreter.to_string(),
            "-m".to_string(),
            "build".to_string(),
            "--sdist".to_string(),
            "--wheel".to_string(),
            "--outdir".to_string(),
            outdir.to_string_lossy().into_owned(),
        ],
        cwd: workspace_root.join(package_dir),
    })
}

/// `twine upload` of exactly `files`, never a glob or `--skip-existing`, which skips by name without comparing bytes.
pub fn pypi_upload_argv(workspace_root: &Path, package_dir: &Path, index: Option<&str>, files: &[PathBuf]) -> Argv {
    let mut args = vec!["upload".to_string()];
    if let Some(index) = index {
        args.push("--repository-url".to_string());
        args.push(index.to_string());
    }
    args.extend(files.iter().map(|file| file.to_string_lossy().into_owned()));
    Argv {
        program: "twine".to_string(),
        args,
        cwd: workspace_root.join(package_dir),
    }
}

/// Resolves the interpreter for the PyPI build step's `python -m build`:
/// prefers `python3` -- the only name macOS and Debian systems guarantee --
/// and falls back to bare `python` for systems that only ship that. Errors
/// naming both when neither is on `path_value`.
///
/// `path_value` is injected rather than read from `$PATH` directly so tests
/// can exercise both resolutions and the error without mutating process-wide
/// environment state.
fn resolve_python_interpreter(path_value: Option<&OsStr>) -> Result<&'static str, GraphError> {
    if exists_on_path("python3", path_value) {
        Ok("python3")
    } else if exists_on_path("python", path_value) {
        Ok("python")
    } else {
        Err(GraphError::ReleasePreconditionUnmet {
            requirement: ReleasePreconditionRequirement::PythonInterpreterOnPath,
        })
    }
}

